// RN-212/213: Convocar primeira pessoa em espera
const inscricoes = banco.listarInscricoesPorAtividade(atividade.id);
const emEspera = inscricoes
  .filter(i => i.status === 'em_espera')
  .sort((a, b) => new Date(a.criadaEm) - new Date(b.criadaEm));

if (emEspera.length > 0) {
    const primeira = emEspera[0];
    primeira.status = 'convocada';
    primeira.convocadaAte = new Date(agora().getTime() + 2 * 60 * 60 * 1000).toISOString();
    primeira.posicaoNaEspera = null;
    banco.atualizarInscricao(primeira);
}

// RN-204: Recomputar posicoes
const restantes = inscricoes.filter(i => i.status === 'em_espera' && i.id !== (emEspera.length > 0 ? emEspera[0].id : null));
restantes.sort((a, b) => new Date(a.criadaEm) - new Date(b.criadaEm));
restantes.forEach((i, index) => {
    i.posicaoNaEspera = index + 1;
    banco.atualizarInscricao(i);
});

