process.env.MODO_TESTE = '1';
const request = require('supertest');
const { criarServidor } = require('../src/app');

describe('M2-RN-208 — Limite de Minicursos', () => {
  let app;
  beforeEach(() => { app = criarServidor(); });

  it('recusa 4º minicurso com 422 LIMITE_DE_MINICURSOS', async () => {
    await request(app).post('/_teste/reset').expect(204);
    const dias = [
      ['2026-10-19T19:00:00-03:00', '2026-10-19T21:00:00-03:00'],
      ['2026-10-20T19:00:00-03:00', '2026-10-20T21:00:00-03:00'],
      ['2026-10-21T19:00:00-03:00', '2026-10-21T21:00:00-03:00'],
      ['2026-10-22T19:00:00-03:00', '2026-10-22T21:00:00-03:00'],
    ];
    const ids = [];
    // cria 4 minicursos em dias/horários distintos e salas distintas para evitar outros erros
    const salas = ['sala-101', 'sala-102', 'lab-3', 'auditorio'];
    for (let i = 0; i < 4; i++) {
      const r = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
        titulo: `Mini ${i}`, tipo: 'minicurso', salaId: salas[i], vagas: 20,
        encontros: [
          { inicio: dias[i][0], fim: dias[i][1] },
          { inicio: '2026-10-23T19:00:00-03:00', fim: `2026-10-23T${19 + i}:30:00-03:00` },
        ].slice(0, 2).map((e, idx) => idx === 1 && i > 0 ? { inicio: `2026-10-23T${19 + i}:00:00-03:00`, fim: `2026-10-23T${20 + i}:00:00-03:00` } : e)
      });
      // Ajuste: garantir encontros não sobrepostos entre minicursos: usa dias diferentes no 1º encontro
      ids.push(r.body.id);
    }
    // inscreve nos 3 primeiros (sem conflito pois 1º encontro em dias distintos; 2º encontro ajustado por i)
    for (let i = 0; i < 3; i++) {
      await request(app).post(`/atividades/${ids[i]}/inscricoes`).set('X-Usuario', 'p-carla').expect(201);
    }
    const resp = await request(app).post(`/atividades/${ids[3]}/inscricoes`).set('X-Usuario', 'p-carla');
    expect(resp.status).toBe(422);
    expect(resp.body.erro).toBe('LIMITE_DE_MINICURSOS');
  });
});

